<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../includes/helpers.php';require_once __DIR__.'/../includes/security.php';require_once __DIR__.'/../includes/layout.php';
sendSecurityHeaders();$user=requireRole('hr_admin','super_admin');$db=getDB();$hasPeople=tableExists('workspace_people');$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$id=sanitizeInt($_POST['user_id']??0,1);$department=sanitizeString($_POST['department']??'',80);$title=sanitizeString($_POST['job_title']??'',120);$location=sanitizeString($_POST['location']??'',100);$q=$db->prepare("SELECT id FROM users WHERE id=? AND role='employee'");$q->execute([$id]);if(!$hasPeople||!$id||!$q->fetch()||!$department||!$title||!$location){$message='Provide complete employee details.';}else{$db->prepare('INSERT INTO workspace_people(user_id,department,job_title,location) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE department=VALUES(department),job_title=VALUES(job_title),location=VALUES(location)')->execute([$id,$department,$title,$location]);auditLog('employee_workplace_update','users',$id);$message='Workplace details saved.';}}
$people=$db->query("SELECT u.id,u.full_name,u.email,u.start_date,u.status".($hasPeople?',p.department,p.job_title,p.location,p.avatar_color,p.is_demo':",'General' department,'Team member' job_title,'Remote' location,'#b6a2ed' avatar_color,0 is_demo").' FROM users u '.($hasPeople?'LEFT JOIN workspace_people p ON p.user_id=u.id ':'')."WHERE u.role='employee' ORDER BY u.full_name")->fetchAll();$departments=array_unique(array_filter(array_column($people,'department')));sort($departments);$demoCount=count(array_filter($people,fn($p)=>!empty($p['is_demo'])));pageHead('People'); ?>
<body><div class="app-shell"><?php renderSidebar($user,'people');?><main class="main-content"><?php renderTopbar('Workspace / People',$user);?><div class="page-body"><?php if($demoCount):?><div class="demo-banner"><span>DEMO PROFILES</span><?=$demoCount?> fictional people · no real personal information</div><?php endif;?><div class="overview-heading"><div><h1>A whole lot of talent.</h1><p>Your people, their roles, and everything that makes your team.</p></div><a class="btn btn-primary" href="/admin/create_account.php">＋ Add team member</a></div><?php if($message):?><div class="alert alert-info" role="status"><?=e($message)?></div><?php endif;?><div class="people-toolbar"><input id="people-search" class="form-control" aria-label="Search people" placeholder="⌕  Search by name, role, or location"><select id="people-department" class="form-control" aria-label="Filter department"><option value="">All departments</option><?php foreach($departments as $d):?><option><?=e($d)?></option><?php endforeach;?></select><select id="people-sort" class="form-control" aria-label="Sort people"><option value="name">Name A–Z</option><option value="newest">Newest joined</option></select><button id="people-view" class="btn btn-outline" aria-pressed="false">List view</button></div>
<div class="people-cards" id="people-cards"><?php foreach($people as $person):$parts=explode(' ',$person['full_name']);$initials=substr($parts[0],0,1).substr(end($parts),0,1);$color=preg_match('/^#[a-fA-F0-9]{6}$/',$person['avatar_color']??'')?$person['avatar_color']:'#b6a2ed';?><article class="card person-card" data-person="<?=(int)$person['id']?>" data-name="<?=e($person['full_name'])?>" data-search="<?=e(strtolower(implode(' ',[$person['full_name'],$person['job_title']??'',$person['location']??'',$person['email']])))?>" data-department="<?=e($person['department']??'General')?>" data-start="<?=e($person['start_date']??'')?>"><div class="avatar" style="background:<?=e($color)?>"><?=e($initials)?></div><div><h3><?=e($person['full_name'])?></h3><p><?=e($person['job_title']??'Team member')?></p><p><?=e($person['department']??'General')?> · <?=e($person['location']??'Remote')?></p><?php if($person['is_demo']):?><p class="person-id">FICTIONAL DEMO PROFILE</p><?php endif;?></div><div class="person-card-footer"><small><?=e($person['status'])?></small><button class="btn btn-outline btn-sm" data-profile-open="<?=(int)$person['id']?>">View profile ↗</button></div></article>
<dialog class="profile-dialog" id="person-<?=(int)$person['id']?>" aria-label="<?=e($person['full_name'])?> profile"><button class="btn btn-outline btn-sm" style="float:right" data-profile-close>Close</button><div class="avatar" style="background:<?=e($color)?>"><?=e($initials)?></div><h2><?=e($person['full_name'])?></h2><p><?=e($person['email'])?></p><p class="person-id" style="margin-top:10px"><?=!empty($person['is_demo'])?'FICTIONAL DEMO · ':''?>EMPLOYEE #<?=(int)$person['id']?></p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(generateCsrfToken())?>"><input type="hidden" name="user_id" value="<?=(int)$person['id']?>"><div class="form-group"><label>Department</label><input name="department" class="form-control" maxlength="80" value="<?=e($person['department']??'General')?>" required></div><div class="form-group"><label>Job title</label><input name="job_title" class="form-control" maxlength="120" value="<?=e($person['job_title']??'Team member')?>" required></div><div class="form-group"><label>Location</label><input name="location" class="form-control" maxlength="100" value="<?=e($person['location']??'Remote')?>" required></div><button class="btn btn-primary">Save workplace details</button> <a href="/admin/employees.php" class="btn btn-outline">Manage account</a></form></dialog><?php endforeach;?></div><div class="empty-state" id="people-empty" hidden>No matching people. Try another department or search.</div><p class="people-footer"><span id="people-count"><?=count($people)?></span> people in your workspace</p></div></main></div><?php pageFooter();?><script src="/assets/js/people.js"></script></body></html>
